package com.example.languagereader.data.tts

import java.security.MessageDigest
import java.security.SecureRandom
import java.time.Instant
import java.time.ZoneOffset
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter
import java.util.Locale
import java.util.UUID

internal class EdgeTtsProtocol(
    private val clock: () -> Instant = { Instant.now() },
    private val idGenerator: () -> String = { UUID.randomUUID().toString().replace("-", "") },
    private val secureRandom: SecureRandom = SecureRandom()
) {
    private var clockSkewSeconds: Long = 0

    fun validate(request: TtsRequest): EdgeTtsRequest {
        val text = request.text.trim()
        if (text.isEmpty()) throw TtsException.EmptyText()
        if (text.length > MAX_TEXT_LENGTH) throw TtsException.TextTooLong()

        val voice = normalizeVoice(request.voice)
        validateRate(request.rate)

        return EdgeTtsRequest(text = text, voice = voice, rate = request.rate)
    }

    fun webSocketUrl(connectionId: String = connectId()): String {
        return "$WSS_URL&ConnectionId=$connectionId" +
            "&Sec-MS-GEC=${generateSecMsGec()}" +
            "&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION"
    }

    fun webSocketHeaders(muid: String = generateMuid()): Map<String, String> {
        return mapOf(
            "Pragma" to "no-cache",
            "Cache-Control" to "no-cache",
            "Origin" to "chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold",
            "User-Agent" to USER_AGENT,
            "Accept-Encoding" to "gzip, deflate, br, zstd",
            "Accept-Language" to "en-US,en;q=0.9",
            "Cookie" to "muid=$muid;"
        )
    }

    fun speechConfigMessage(): String {
        return "X-Timestamp:${timestamp()}\r\n" +
            "Content-Type:application/json; charset=utf-8\r\n" +
            "Path:speech.config\r\n\r\n" +
            "{\"context\":{\"synthesis\":{\"audio\":{\"metadataoptions\":{" +
            "\"sentenceBoundaryEnabled\":\"true\",\"wordBoundaryEnabled\":\"false\"" +
            "},\"outputFormat\":\"audio-24khz-48kbitrate-mono-mp3\"}}}}\r\n"
    }

    fun ssmlMessage(request: EdgeTtsRequest, requestId: String = connectId()): String {
        return "X-RequestId:$requestId\r\n" +
            "Content-Type:application/ssml+xml\r\n" +
            "X-Timestamp:${timestamp()}Z\r\n" +
            "Path:ssml\r\n\r\n" +
            "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='en-US'>" +
            "<voice name='${request.voice}'>" +
            "<prosody pitch='+0Hz' rate='${request.rate}' volume='+0%'>" +
            escapeForSsml(removeIncompatibleCharacters(request.text)) +
            "</prosody>" +
            "</voice>" +
            "</speak>"
    }

    fun pathFromTextFrame(text: String): String? {
        val headerText = text.substringBefore("\r\n\r\n")
        return parseHeaders(headerText.toByteArray(Charsets.UTF_8))["Path"]
    }

    fun audioFromBinaryFrame(frame: ByteArray): ByteArray? {
        if (frame.size < 2) {
            throw TtsException.UpstreamUnavailable("TTS upstream returned an invalid audio frame")
        }

        val headerLength = ((frame[0].toInt() and 0xff) shl 8) or
            (frame[1].toInt() and 0xff)
        val headerEnd = 2 + headerLength
        if (headerEnd > frame.size) {
            throw TtsException.UpstreamUnavailable("TTS upstream returned an invalid audio frame")
        }

        val headers = parseHeaders(frame.copyOfRange(2, headerEnd))
        if (headers["Path"] != "audio") {
            throw TtsException.UpstreamUnavailable("TTS upstream returned a non-audio frame")
        }

        val data = frame.copyOfRange(headerEnd, frame.size)
        val contentType = headers["Content-Type"]
        if (contentType == null) {
            if (data.isEmpty()) return null
            throw TtsException.UpstreamUnavailable("TTS upstream returned an invalid terminal frame")
        }
        if (contentType != "audio/mpeg") {
            throw TtsException.UpstreamUnavailable("TTS upstream returned unsupported audio content")
        }
        if (data.isEmpty()) {
            throw TtsException.UpstreamUnavailable("TTS upstream returned an empty audio frame")
        }

        return data
    }

    fun adjustClockSkewFromServerDate(serverDate: String?): Boolean {
        if (serverDate.isNullOrBlank()) return false
        val parsed = runCatching {
            ZonedDateTime.parse(serverDate, DateTimeFormatter.RFC_1123_DATE_TIME)
                .toInstant()
        }.getOrNull() ?: return false
        clockSkewSeconds = parsed.epochSecond - clock().epochSecond
        return true
    }

    fun generateSecMsGec(): String {
        val roundedUnixSeconds = ((clock().epochSecond + clockSkewSeconds) / 300) * 300
        val windowsFileTimeTicks = (roundedUnixSeconds + WIN_EPOCH_SECONDS) * TICKS_PER_SECOND
        val tokenPayload = "$windowsFileTimeTicks$TRUSTED_CLIENT_TOKEN"
        val digest = MessageDigest.getInstance("SHA-256")
            .digest(tokenPayload.toByteArray(Charsets.US_ASCII))
        return digest.joinToString("") { "%02x".format(it) }.uppercase(Locale.US)
    }

    fun connectId(): String = idGenerator().replace("-", "")

    private fun timestamp(): String {
        return TIMESTAMP_FORMATTER.format(clock().atZone(ZoneOffset.UTC))
    }

    private fun generateMuid(): String {
        val bytes = ByteArray(16)
        secureRandom.nextBytes(bytes)
        return bytes.joinToString("") { "%02x".format(it) }.uppercase(Locale.US)
    }

    private fun normalizeVoice(voice: String): String {
        if (voice.isBlank()) throw TtsException.InvalidVoice("voice is required")

        if (FULL_VOICE_PATTERN.matches(voice)) return voice

        val match = SHORT_VOICE_PATTERN.matchEntire(voice)
            ?: throw TtsException.InvalidVoice("Invalid voice '$voice'")

        val lang = match.groupValues[1]
        var region = match.groupValues[2]
        var name = match.groupValues[3]
        val dashIndex = name.indexOf('-')
        if (dashIndex != -1) {
            region = "$region-${name.substring(0, dashIndex)}"
            name = name.substring(dashIndex + 1)
        }

        return "Microsoft Server Speech Text to Speech Voice ($lang-$region, $name)"
    }

    private fun validateRate(rate: String) {
        if (!RATE_PATTERN.matches(rate)) {
            throw TtsException.InvalidRate("rate must be an edge-tts SSML rate like '+0%' or '-50%'")
        }
        val numeric = rate.removeSuffix("%").toInt()
        if (numeric < MIN_RATE_PERCENT || numeric > MAX_RATE_PERCENT) {
            throw TtsException.InvalidRate(
                "rate must be between $MIN_RATE_PERCENT% and $MAX_RATE_PERCENT%"
            )
        }
    }

    private fun removeIncompatibleCharacters(text: String): String {
        return buildString(text.length) {
            text.forEach { char ->
                val code = char.code
                append(
                    if ((code in 0..8) || (code in 11..12) || (code in 14..31)) {
                        ' '
                    } else {
                        char
                    }
                )
            }
        }
    }

    private fun escapeForSsml(text: String): String {
        return text
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
    }

    private fun parseHeaders(bytes: ByteArray): Map<String, String> {
        val headerText = bytes.toString(Charsets.UTF_8)
        if (headerText.isBlank()) return emptyMap()

        return headerText.split("\r\n")
            .filter { it.isNotBlank() }
            .associate { line ->
                val separator = line.indexOf(':')
                if (separator <= 0) {
                    throw TtsException.UpstreamUnavailable(
                        "TTS upstream returned malformed frame headers"
                    )
                }
                line.substring(0, separator) to line.substring(separator + 1)
            }
    }

    companion object {
        private const val MAX_TEXT_LENGTH = 500
        private const val MIN_RATE_PERCENT = -90
        private const val MAX_RATE_PERCENT = 100

        private const val TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
        private const val BASE_URL = "speech.platform.bing.com/consumer/speech/synthesize/readaloud"
        private const val WSS_URL =
            "wss://$BASE_URL/edge/v1?TrustedClientToken=$TRUSTED_CLIENT_TOKEN"
        private const val CHROMIUM_FULL_VERSION = "143.0.3650.75"
        private const val CHROMIUM_MAJOR_VERSION = "143"
        private const val SEC_MS_GEC_VERSION = "1-$CHROMIUM_FULL_VERSION"
        private const val USER_AGENT =
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
                "(KHTML, like Gecko) Chrome/$CHROMIUM_MAJOR_VERSION.0.0.0 Safari/537.36 " +
                "Edg/$CHROMIUM_MAJOR_VERSION.0.0.0"

        private const val WIN_EPOCH_SECONDS = 11_644_473_600L
        private const val TICKS_PER_SECOND = 10_000_000L

        private val SHORT_VOICE_PATTERN = Regex("^([a-z]{2,})-([A-Z]{2,})-(.+Neural)$")
        private val FULL_VOICE_PATTERN =
            Regex("^Microsoft Server Speech Text to Speech Voice \\(.+,.+\\)$")
        private val RATE_PATTERN = Regex("^[+-]\\d+%$")
        private val TIMESTAMP_FORMATTER =
            DateTimeFormatter.ofPattern(
                "EEE MMM dd yyyy HH:mm:ss 'GMT+0000 (Coordinated Universal Time)'",
                Locale.US
            )
    }
}

